SourceCode.Declaration:
/// <summary>
/// Single-threaded post worker for ONE transaction type over the WHOLE selection.
/// Exactly one instance of this task runs per phase, gated (via batch task
/// dependencies) to start only after all parallel create-trans tasks of the same
/// type have finished. Rebate posting is single-threaded by design in standard
/// (there is no TAMRebatePost split task) because it writes to shared ledger,
/// subledger and voucher number sequences that are not partitioned by deal.
/// </summary>
internal final class METRebatePostTask extends RunBaseBatch implements BatchRetryable
{
    private container dealRecIds;
    private TAMRebateTransactionType rebateTransactionType;
    private TAMRebateFromDate fromDate;
    private TAMRebateToDate toDate;
    private TransDate transDate;

    #DEFINE.CurrentVersion(1)

}

Method.Source:
internal static METRebatePostTask construct(
    TAMRebateTransactionType _type,
    container _dealRecIds,
    TAMRebateFromDate _f,
    TAMRebateToDate _t,
    TransDate _td)
{
    METRebatePostTask task = new METRebatePostTask();
    task.rebateTransactionType = _type;
    task.dealRecIds = _dealRecIds;
    task.fromDate = _f;
    task.toDate = _t;
    task.transDate = _td;

    return task;
}

public void run()
{
    METRebateCombinedFlow::post(rebateTransactionType, dealRecIds, fromDate, toDate, transDate);
}

public container pack()
{
    return [#CurrentVersion, dealRecIds, rebateTransactionType, fromDate, toDate, transDate];
}

public boolean unpack(container _p)
{
    Integer version = conPeek(_p, 1);
    if (version != #CurrentVersion)
    {
        return false;
    }

    [version, dealRecIds, rebateTransactionType, fromDate, toDate, transDate] = _p;

    return true;
}

public ClassDescription caption()
{
    return strFmt("Rebate post (%1)", enum2str(rebateTransactionType));
}

[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}
